/**
 * Builds supabase/apply-all.sql: the rate-limit RPC plus the enterprise migration in
 * one transaction, for a single paste into the Supabase SQL editor.
 * Usage: npm run sql:bundle (re-run after editing either source file).
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const SOURCES = ['supabase/rate-limit.sql', 'supabase/migrations/20261019_enterprise_multitenant.sql']
const OUTPUT = 'supabase/apply-all.sql'

const header = `-- ===========================================================================
-- GENERATED by scripts/bundle-sql.ts from:
${SOURCES.map((source) => `--   ${source}`).join('\n')}
-- Do not edit by hand; edit the sources and run \`npm run sql:bundle\`.
--
-- Paste into the Supabase SQL editor and run once. Idempotent and transactional:
-- it either applies completely or not at all, and is safe to re-run.
-- Prerequisite: the base tables from supabase/schema.sql exist (true for production).
-- ===========================================================================

begin;
`

const footer = `
commit;

-- ===========================================================================
-- NEXT STEP (manual): grant dashboard access. RLS and /api only return data for
-- tenant_members rows. Create the user under Authentication -> Users (or invite
-- them), then run, replacing the e-mail:
--
--   insert into public.tenant_members (tenant_id, user_id, role)
--   select t.id, u.id, 'owner'
--   from public.tenants t
--   cross join auth.users u
--   where t.whatsapp_instance_id = '710722751571'
--     and u.email = 'owner@example.com'
--   on conflict (tenant_id, user_id) do update set role = excluded.role;
-- ===========================================================================
`

const body = SOURCES.map((source) => {
  const sql = readFileSync(resolve(process.cwd(), source), 'utf8').replace(/\r\n/g, '\n').trim()
  return `\n-- ---------------------------------------------------------------------------\n-- BEGIN ${source}\n-- ---------------------------------------------------------------------------\n\n${sql}\n\n-- END ${source}\n`
}).join('')

writeFileSync(resolve(process.cwd(), OUTPUT), `${header}${body}${footer}`, 'utf8')
console.log(`Wrote ${OUTPUT} from ${SOURCES.length} sources`)
